6	/**
7	 * Deployment-confirmation email helper.
8	 *
9	 * Sends the "your server is ready" email once a server is provisioned and
10	 * reachable, from BOTH the provision success path (worker) and the admin
11	 * "reconcile from Proxmox" recovery. It is deliberately:
12	 *
13	 *  - TRANSACTIONAL: sent with the CRITICAL `provision_ready` kind so a customer
14	 *    preference can never suppress it (see lib/prefs.ts).
15	 *  - DEDUPED via `EmailLog`: `EmailLog` has no `serverId` column and we add no
16	 *    schema, so the dedupe keys on the template tag + the customer + the
17	 *    server-unique dashboard path that the rendered HTML always contains. Only
18	 *    a prior SENT row blocks a resend, so a failed attempt can still be retried
19	 *    on the next reconcile/provision.
20	 *  - BEST-EFFORT: it runs on the provision money-path, so it swallows every
21	 *    error and NEVER throws into the caller.
22	 */
23	
24	const DEPLOY_TEMPLATE = "server_deployed";
25	
26	type DeployedServer = {
27	  id: string;
28	  hostname: string;
29	  sshPort: number | null;
30	  userId: string;
31	  plan?: { name?: string | null } | null;
32	  node?: { publicIp?: string | null } | null;
33	};
34	
35	type DeployedUser = { email?: string | null } | null | undefined;
36	
37	export async function sendServerDeployedEmail(
38	  server: DeployedServer,
39	  user: DeployedUser
40	): Promise<void> {
41	  try {
42	    const email = user?.email;
43	    if (!email) return;
44	
45	    const dashboardUrl = `${appUrl()}/dashboard/servers/${server.id}`;
46	
47	    // Per-server dedupe (see file header). The dashboard path is server-unique
48	    // and survives EmailLog redaction (only secret query params are stripped).
49	    const already = await db.emailLog.findFirst({
50	      where: {
51	        template: DEPLOY_TEMPLATE,
52	        userId: server.userId,
53	        status: "SENT",
54	        html: { contains: `/dashboard/servers/${server.id}` },
55	      },
56	      select: { id: true },
57	    });
58	    if (already) return;
59	
60	    // ALWAYS the node's public IP + forwarded ssh port — never the internal
61	    // 10.20.x.x address, which is unreachable from outside the host.
62	    const host = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
63	    const sshEndpoint = server.sshPort ? `${host}:${server.sshPort}` : host;
64	
65	    const tpl = emails.serverDeployed({
66	      hostname: server.hostname,
67	      planName: server.plan?.name ?? "Nxeon",
68	      sshEndpoint,
69	      dashboardUrl,
70	    });
71	
72	    await sendMail({
73	      to: email,
74	      subject: tpl.subject,
75	      html: tpl.html,
76	      // Records EmailLog.template = "server_deployed" — the dedupe key above.
77	      template: tpl.template,
78	      userId: server.userId,
79	      // CRITICAL kind → non-suppressible transactional delivery.
80	      kind: "provision_ready",
81	    });
82	  } catch (e) {
83	    console.error("[server-deployed-email] send failed (non-fatal)", e);
84	  }
85	}
